#include <stdio.h>
#include <limits.h>

int main(void) {
    long long n, k, a[100000];
    long long i, j, index = 0, sum, z, min = LLONG_MAX;

    scanf("%lld %lld", &n, &k);
    for (i = 0; i < n; i++)
        scanf("%lld", &a[i]);

    if (k == 1) {
        printf("1\n");
        return 0;
    }

    if (k == n) {
        for (i = 0; i < n; i++) {
            if (a[i] < min) {
                min = a[i];
                index = i;
            }
        }
    } else {
        for (i = 0; i < k; i++) {
            sum = 0;
            z = i;
            while (z < n) {
                sum += a[z];
                z += k;
            }
            if (sum < min) {
                min = sum;
                index = i;
            }
        }
    }

    printf("%lld\n", index + 1);
    return 0;
}

